diagrams.approved_source:
@startuml
title Autonomous milestone lifecycle (proposed)
start
:Load persistent run and repository facts;
:Reconcile uncertain child operations;
if (Eligible approved scope?) then (yes)
 :Prepare explanation and diagrams;
 :Register requirements;
 if (Requirements approved?) then (yes)
  :Generate and validate design;
  if (Validated design approved?) then (yes)
   :Prepare approved DAG and exact execution requests;
   :Run existing scheduler within budgets;
   :Independent AEO-4 verification;
   if (Quality accepted?) then (yes)
    :Prepare AEO-5 manifest and publication gate;
    :Observe permitted delivery and generate report;
   else (no)
    :Bounded permitted remediation or checkpoint;
   endif
  else (no)
   :Persist design checkpoint;
  endif
 else (no)
  :Persist requirements checkpoint;
 endif
else (no)
 :Persist blocked report;
endif
stop
@enduml

@startuml
title Durable intent and interruption recovery
start
:Load run intent, child IDs, reservations and audit;
if (Unfinished operation?) then (yes)
 :Inspect existing task claims, execution records,
 worktrees and delivery operations;
 if (Verified completed child outcome?) then (yes)
  :Independently validate artifacts and adopt once;
 else (no)
  if (Confirmed safe retry with authority?) then (yes)
   :Reserve remaining attempt budget;
   :Dispatch through existing child recovery service;
  else (no)
   :Persist RECOVERY_REQUIRED;
   :Present precise human decision and evidence;
   stop
  endif
 endif
else (no)
 :Recheck current approvals and repository facts;
endif
:Persist observed transition and audit;
:Select one permitted next operation;
stop
@enduml

@startuml
title Future application design and delivery dependency boundaries
package "agrosphere-architecture" {
 rectangle "Approved cross-service design" as Arch
}
package "agrosphere-contracts" {
 rectangle "Versioned API / event contracts" as Contracts
}
package "Discovered service repository A" {
 rectangle "Service design and task A" as ServiceA
}
package "Discovered service repository B" {
 rectangle "Service design and task B" as ServiceB
}
package "agrosphere-orchestrator" {
 rectangle "Run manifest / task DAG / artifact hashes" as Run
 rectangle "AEO-5 unit dependency state" as Units
}
Arch --> Contracts : approved impact only
Arch --> ServiceA : design requirement references
Arch --> ServiceB : design requirement references
Contracts --> ServiceA : pinned compatible version
Contracts --> ServiceB : pinned compatible version
Run --> ServiceA : exact isolated execution authority
Run --> ServiceB : only when prerequisites available
ServiceA --> Units : verified commits and QA
ServiceB --> Units : verified commits and QA
note bottom of Units
A PR existing does not make dependency content available.
No sibling source dependency or cross-service SQL.
end note
@enduml

